set -euo pipefail; EXPECTED='eb10cdd70039e82d09cc03231b52ad851fe42546'; PKG='io.blueeye'; git fetch --no-tags origin main >/dev/null; test "$(git rev-parse origin/main)" = "${EXPECTED}"; SERIAL=$(adb devices | awk 'NR>1 && $2=="device" {print $1}' | head -n1); test -n "${SERIAL}"; TMP=$(mktemp -d); trap 'rm -rf "${TMP}"' EXIT; XML="${TMP}/window.xml"; dump(){ adb -s "${SERIAL}" shell uiautomator dump /sdcard/blueeye-final.xml >/dev/null; adb -s "${SERIAL}" exec-out cat /sdcard/blueeye-final.xml > "${XML}"; }; coords(){ dump; python3 tools/ui-smoke/ui_node.py "${XML}" "$1" "$2"; }; tap(){ C=$(coords "$1" "$2"); test -n "${C}"; set -- ${C}; adb -s "${SERIAL}" shell input tap "$1" "$2"; sleep 0.8; }; scroll_until(){ for i in 1 2 3 4 5 6 7 8; do if coords text "$1" >/dev/null 2>&1; then return 0; fi; adb -s "${SERIAL}" shell input swipe 540 1750 540 550 350; sleep 0.6; done; return 1; }; rows(){ dump; python3 - "${XML}" <<'PY'
import re,sys,xml.etree.ElementTree as ET
r=re.compile(r'\[(\d+),(\d+)\]\[(\d+),(\d+)\]')
a=[]
for n in ET.parse(sys.argv[1]).getroot().iter('node'):
 t=(n.attrib.get('text') or '').strip(); m=r.fullmatch(n.attrib.get('bounds',''))
 if t and m:
  x1,y1,x2,y2=map(int,m.groups()); a.append(((y1+y2)//2,(x1+x2)//2,t))
for y,x,t in sorted(a): print(f'{y:4d} {x:4d} {t}')
PY
}; echo '--- return to Radar and stop scanning normally ---'; adb -s "${SERIAL}" shell input keyevent BACK; sleep 0.8; tap content-desc Menu; tap text Radar; echo 'radar_before_stop:'; rows | grep -E 'Paused|seen|needs review|suspicious|nearby|All [0-9]+' || true; tap content-desc Scan; sleep 2; echo 'radar_after_stop:'; rows | grep -E 'Paused|seen|needs review|suspicious|nearby|All [0-9]+' || true; echo '--- frozen diagnostics ---'; tap content-desc Menu; tap text Settings; tap text 'Alerts & Collection'; scroll_until 'Queue dropped'; rows | grep -E 'Runtime profile|STABLE_CORE|Scanner|Running|Idle|Ingest window|BLE last seen|Raw BLE/min|Queued/min|Coalesced/min|Processed/min|Persisted/min|Signal samples/min|Raw / queued / coalesced total|Processed / persisted / samples total|Queue depth|Queue high-water|Queue rejected|Queue dropped|Processing failed|Provisional discard|Sample write failed|Queue wait avg/max|Processing avg/max|Last scan error|Lifecycle|RUNNING|STOP' || true; echo '--- session export Copy ---'; adb -s "${SERIAL}" shell input keyevent BACK; sleep 0.7; tap text 'Database & Updates'; scroll_until 'Copy'; tap text Copy; sleep 3; echo 'clipboard_services:'; adb -s "${SERIAL}" shell cmd -l | grep -i clipboard || true; echo 'clipboard_cmd_shell:'; adb -s "${SERIAL}" shell cmd clipboard get 2>&1 | head -c 500 || true; echo; echo 'clipboard_cmd_run_as:'; adb -s "${SERIAL}" shell run-as "${PKG}" cmd clipboard get 2>&1 | head -c 500 || true; echo; echo 'clipboard_dumpsys:'; adb -s "${SERIAL}" shell dumpsys clipboard 2>&1 | head -c 1200 || true; echo; echo '--- Room/WAL/SHM live stopped-scan snapshot ---'; adb -s "${SERIAL}" shell run-as "${PKG}" sh -c 'ls -al databases'; adb -s "${SERIAL}" exec-out run-as "${PKG}" sh -c 'cd /data/user/0/io.blueeye && tar cf - databases' > "${TMP}/databases.tar"; mkdir -p "${TMP}/dbcopy"; tar xf "${TMP}/databases.tar" -C "${TMP}/dbcopy"; DB="${TMP}/dbcopy/databases/tracker_database"; test -f "${DB}"; echo 'snapshot_files:'; ls -al "${TMP}/dbcopy/databases"; echo 'snapshot_sha256:'; for f in "${TMP}/dbcopy/databases"/*; do if command -v shasum >/dev/null; then shasum -a 256 "$f"; else sha256sum "$f"; fi; done; echo 'sqlite_integrity:'; sqlite3 "${DB}" 'PRAGMA integrity_check;'; echo 'sqlite_user_version:'; sqlite3 "${DB}" 'PRAGMA user_version;'; echo 'table_counts:'; for T in $(sqlite3 "${DB}" "select name from sqlite_master where type='table' and name not like 'sqlite_%' and name not like 'room_%' order by name;"); do printf '%s=' "$T"; sqlite3 "${DB}" "select count(*) from \"$T\";"; done; echo '--- final logcat ---'; PID=$(adb -s "${SERIAL}" shell pidof "${PKG}" | tr -d '\r' || true); echo "pid=${PID:-not_running}"; if [ -n "${PID}" ]; then adb -s "${SERIAL}" logcat --pid="${PID}" -d -v threadtime > "${TMP}/app.log" || true; echo "app_log_lines=$(wc -l < "${TMP}/app.log" | tr -d ' ')"; echo "error_like_count=$(grep -Eic 'FATAL|ANR|Exception|SecurityException|DeadObject|OutOfMemory|SQLite.*(error|exception)|Room.*(error|exception)' "${TMP}/app.log" || true)"; grep -Ei 'FATAL|ANR|Exception|SecurityException|DeadObject|OutOfMemory|SQLite.*(error|exception)|Room.*(error|exception)' "${TMP}/app.log" | tail -n 80 || true; fi; echo 'global_crash_markers:'; adb -s "${SERIAL}" logcat -d -v threadtime | grep -E 'FATAL EXCEPTION|ANR in io.blueeye|Process: io.blueeye|am_crash|am_anr' | tail -n 80 || true; echo 'PHONE_FINAL_CAPTURE=PASS'
